import {
  attachments,
  comments,
  getDb,
  issueLabels,
  issues,
  projectIssueCounters,
} from "@/server/db";

input.old_string:
/**
 * Next per-project issue number. Archived issues keep their number, so the
 * max is taken over every row rather than the live ones.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  return (row?.value ?? 0) + 1;
}

input.new_string:
/**
 * Highest number ever issued in the project: the larger of the numbers still
 * on rows here and the floor recorded when a number was allocated or retired.
 * Archived issues keep their number, so the row max covers every row, not only
 * the live ones.
 */
function highestIssuedNumber(orgId: OrgId, projectId: ProjectId): number {
  const row = getDb()
    .select({ value: sql<number | null>`max(${issues.number})` })
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
    )
    .get();
  const floor = getDb()
    .select({ lastNumber: projectIssueCounters.lastNumber })
    .from(projectIssueCounters)
    .where(
      and(
        orgPredicate(projectIssueCounters.orgId, orgId),
        eq(projectIssueCounters.projectId, projectId),
      ),
    )
    .get();
  return Math.max(row?.value ?? 0, floor?.lastNumber ?? 0);
}

/** Raises the project's issued-number floor. Never lowers it. */
function raiseIssuedNumberFloor(
  orgId: OrgId,
  projectId: ProjectId,
  floor: number,
): void {
  getDb()
    .insert(projectIssueCounters)
    .values({ orgId, projectId, lastNumber: floor })
    .onConflictDoUpdate({
      target: [projectIssueCounters.orgId, projectIssueCounters.projectId],
      set: {
        lastNumber: sql`max(${projectIssueCounters.lastNumber}, ${floor})`,
      },
    })
    .run();
}

/**
 * Next per-project issue number. Allocating remembers the number, so a later
 * move of the row cannot make it available again.
 */
export async function nextIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<number> {
  const next = highestIssuedNumber(orgId, projectId) + 1;
  raiseIssuedNumberFloor(orgId, projectId, next);
  return next;
}

/**
 * Retires `number` in the project that issued it. Called when an issue leaves,
 * so the number is not reissued after the row no longer counts toward the max.
 */
export async function retireIssueNumber(
  orgId: OrgId,
  projectId: ProjectId,
  number: number,
): Promise<void> {
  raiseIssuedNumberFloor(orgId, projectId, number);
}

/**
 * Moves an issue onto another project under a number already allocated there.
 * Labels, comments and attachments stay on the issue id and are not rewritten.
 */
export async function moveIssueToProject(
  orgId: OrgId,
  issueId: IssueId,
  projectId: ProjectId,
  issueNumber: number,
): Promise<Issue> {
  const row = getDb()
    .update(issues)
    .set({
      projectId,
      number: issueNumber,
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(and(orgPredicate(issues.orgId, orgId), eq(issues.id, issueId)))
    .returning()
    .get();

  if (!row) throw new Error(`Issue ${issueId} not found`);

  const labels = await listLabelsForIssues(orgId, [issueId]);
  return toIssue(row, (labels[issueId] ?? []).map((label) => label.id));
}

/**
