/**
 * Leaves the issue's project and joins `toProjectId` in the same workspace.
 * The target allocates the next issue number exactly as a create would, and
 * the number left behind is retired. A move onto the project the issue is
 * already in changes nothing and publishes nothing.
 */
export async function moveIssueToProject(
  actor: Actor,
  input: MoveIssueToProjectInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );

  if (before.projectId === input.toProjectId) {
    return before;
  }

  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.toProjectId),
    "Project",
    input.toProjectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.toProjectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const toNumber = await issueRepo.nextIssueNumber(input.orgId, input.toProjectId);
  await issueRepo.retireIssueNumber(input.orgId, before.projectId, before.number);
  const after = await issueRepo.moveIssueToProject(
    input.orgId,
    input.issueId,
    input.toProjectId,
    toNumber,
  );

  await emit("issue.moved", {
    ...actorEnvelope(actor),
    issueId: after.id,
    fromProjectId: before.projectId,
    toProjectId: after.projectId,
    fromNumber: before.number,
    toNumber: after.number,
  });

  return after;
}

